#include <array>
#include <cstdint>
#include <string>
#include <utility>

struct Guid
{
    std::uint32_t a;
    std::uint16_t b, c;
    std::array<std::uint8_t, 8> d;
    bool operator==(const Guid&) const = default;
};

using HRESULT = std::int32_t;
constexpr HRESULT S_OK = 0;
constexpr HRESULT E_NOINTERFACE = static_cast<HRESULT>(0x80004002u);
constexpr HRESULT E_POINTER = static_cast<HRESULT>(0x80004003u);

constexpr Guid IID_IUnknown{ 0x00000000, 0x0000, 0x0000, { 0xC0, 0, 0, 0, 0, 0, 0, 0x46 } };
constexpr Guid IID_IShape{ 0x6A1B2C3D, 0x1111, 0x4A4A, { 1, 2, 3, 4, 5, 6, 7, 8 } };
constexpr Guid IID_INamed{ 0x6A1B2C3E, 0x2222, 0x4B4B, { 8, 7, 6, 5, 4, 3, 2, 1 } };

struct IUnknownLike
{
    virtual HRESULT QueryInterface(const Guid& iid, void** out) = 0;
    virtual std::uint32_t AddRef() = 0;
    virtual std::uint32_t Release() = 0;
protected:
    virtual ~IUnknownLike() = default;
};

struct IShape : IUnknownLike { virtual double area() = 0; };
struct INamed : IUnknownLike { virtual std::string name() = 0; };

inline int g_liveObjects{ 0 };

namespace
{
    class Square final : public IShape, public INamed
    {
    public:
        explicit Square(double side) : side_{ side } { ++g_liveObjects; }

        HRESULT QueryInterface(const Guid& iid, void** out) override
        {
            if (!out) return E_POINTER;
            if (iid == IID_IShape || iid == IID_IUnknown) *out = static_cast<IShape*>(this);
            else if (iid == IID_INamed) *out = static_cast<INamed*>(this);
            else
            {
                *out = nullptr;
                return E_NOINTERFACE;
            }
            AddRef();
            return S_OK;
        }

        std::uint32_t AddRef() override { return ++count_; }

        std::uint32_t Release() override
        {
            const std::uint32_t left{ --count_ };
            if (left == 0) delete this;
            return left;
        }

        double area() override { return side_ * side_; }
        std::string name() override { return "square"; }

    private:
        ~Square() override { --g_liveObjects; }
        double side_;
        std::uint32_t count_{ 1 };
    };
}

HRESULT createSquare(double side, IShape** out)
{
    if (!out) return E_POINTER;
    *out = new Square(side);
    return S_OK;
}

template <typename T>
class Ptr
{
public:
    Ptr() = default;
    Ptr(std::nullptr_t) {}
    Ptr(T* p) : p_{ p } { if (p_) p_->AddRef(); }
    Ptr(const Ptr& other) : p_{ other.p_ } { if (p_) p_->AddRef(); }
    Ptr(Ptr&& other) noexcept : p_{ std::exchange(other.p_, nullptr) } {}

    Ptr& operator=(const Ptr& other)
    {
        if (other.p_) other.p_->AddRef();
        T* old{ std::exchange(p_, other.p_) };
        if (old) old->Release();
        return *this;
    }

    Ptr& operator=(Ptr&& other) noexcept
    {
        if (this != &other)
        {
            T* old{ std::exchange(p_, std::exchange(other.p_, nullptr)) };
            if (old) old->Release();
        }
        return *this;
    }

    ~Ptr() { reset(); }

    T* get() const { return p_; }
    T* operator->() const { return p_; }
    explicit operator bool() const { return p_ != nullptr; }

    void reset()
    {
        if (T* old{ std::exchange(p_, nullptr) }) old->Release();
    }

    T** address()
    {
        reset();
        return &p_;
    }

    template <typename U>
    HRESULT as(Ptr<U>& out, const Guid& iid) const
    {
        if (!p_) return E_POINTER;
        return p_->QueryInterface(iid, reinterpret_cast<void**>(out.address()));
    }

private:
    T* p_{ nullptr };
};

unitTests:
TEST("creating and releasing by hand") {
    IShape* shape{ nullptr };
    CHECK_EQ(createSquare(3, &shape), S_OK);
    CHECK_EQ(g_liveObjects, 1);
    CHECK_EQ(shape->area(), 9.0);
    CHECK_EQ(shape->AddRef(), 2u);
    CHECK_EQ(shape->Release(), 1u);
    CHECK_EQ(shape->Release(), 0u);
    CHECK_EQ(g_liveObjects, 0);
    CHECK_EQ(createSquare(1, nullptr), E_POINTER);
}
TEST("QueryInterface") {
    IShape* shape{ nullptr };
    createSquare(2, &shape);
    INamed* named{ nullptr };
    CHECK_EQ(shape->QueryInterface(IID_INamed, reinterpret_cast<void**>(&named)), S_OK);
    CHECK_EQ(named->name(), std::string("square"));
    IUnknownLike* unknown{ nullptr };
    CHECK_EQ(named->QueryInterface(IID_IUnknown, reinterpret_cast<void**>(&unknown)), S_OK);
    CHECK(static_cast<void*>(unknown) == static_cast<void*>(shape));
    void* none{ &none };
    const Guid other{ 1, 2, 3, { 0, 0, 0, 0, 0, 0, 0, 0 } };
    CHECK_EQ(shape->QueryInterface(other, &none), E_NOINTERFACE);
    CHECK(none == nullptr);
    CHECK_EQ(shape->QueryInterface(IID_IShape, nullptr), E_POINTER);
    CHECK_EQ(unknown->Release(), 2u);
    CHECK_EQ(named->Release(), 1u);
    CHECK_EQ(g_liveObjects, 1);
    shape->Release();
    CHECK_EQ(g_liveObjects, 0);
}
TEST("the smart pointer counts for you") {
    {
        Ptr<IShape> shape;
        CHECK(!shape);
        CHECK_EQ(createSquare(4, shape.address()), S_OK);
        CHECK(static_cast<bool>(shape));
        CHECK_EQ(shape->area(), 16.0);
        Ptr<IShape> copy{ shape };
        Ptr<IShape> moved{ std::move(copy) };
        CHECK(!copy);
        Ptr<INamed> named;
        CHECK_EQ(shape.as(named, IID_INamed), S_OK);
        CHECK_EQ(named->name(), std::string("square"));
        CHECK_EQ(shape->AddRef(), 4u);
        shape->Release();
        Ptr<INamed> nothing;
        const Guid other{ 9, 9, 9, { 0, 0, 0, 0, 0, 0, 0, 0 } };
        CHECK_EQ(shape.as(nothing, other), E_NOINTERFACE);
        CHECK(!nothing);
        CHECK_EQ(g_liveObjects, 1);
    }
    CHECK_EQ(g_liveObjects, 0);
}
TEST("assignment and reset") {
    Ptr<IShape> a, b;
    createSquare(1, a.address());
    createSquare(2, b.address());
    CHECK_EQ(g_liveObjects, 2);
    a = b;
    CHECK_EQ(g_liveObjects, 1);
    CHECK_EQ(a->area(), 4.0);
    a = a;
    CHECK_EQ(a->area(), 4.0);
    b.reset();
    CHECK_EQ(g_liveObjects, 1);
    a = Ptr<IShape>{};
    CHECK_EQ(g_liveObjects, 0);
    IShape* raw{ nullptr };
    createSquare(5, &raw);
    {
        Ptr<IShape> wrapped{ raw };
        CHECK_EQ(raw->AddRef(), 3u);
        raw->Release();
    }
    CHECK_EQ(raw->Release(), 0u);
    CHECK_EQ(g_liveObjects, 0);
}

